-- =====================================================================
-- RADICAL GYM - Actualización 16: MENSAJES PREDETERMINADOS POR CATEGORÍA
-- 15 mensajes por categoría (por vencer, vencidos, no vienen, renovaron,
-- bienvenida, cumpleaños, deuda, congelamiento, constancia, exalumnos),
-- cálidos y editables. Se personalizan con {{nombre}}, {{plan}}, etc.
-- y se envían por WhatsApp desde Notificaciones.
-- Se puede ejecutar varias veces; no borra datos ni pisa mensajes editados.
-- =====================================================================
SET NAMES utf8mb4;
USE gestion_radicalgym;

CREATE TABLE IF NOT EXISTS plantillas_mensajes (
  idplantilla       INT AUTO_INCREMENT PRIMARY KEY,
  categoria         VARCHAR(30)   NOT NULL COMMENT 'por_vencer, vencidos, no_vienen, renovaron, bienvenida, cumpleanos, deuda, congelamiento, constancia, exalumnos',
  titulo            VARCHAR(80)   NOT NULL,
  mensaje           VARCHAR(1000) NOT NULL COMMENT 'Admite {{nombre}}, {{plan}}, {{fecha_vencimiento}}, {{dias}}, {{deuda}}, {{fecha_limite}}, {{gym}}, {{codigo}}, {{fecha_regreso}}, {{asistencias}}',
  orden             SMALLINT      NOT NULL DEFAULT 0,
  es_propia         TINYINT(1)    NOT NULL DEFAULT 0 COMMENT '1 = la escribió el gimnasio',
  activo            TINYINT(1)    NOT NULL DEFAULT 1,
  creado_por        INT           NULL,
  fecha_registro    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  fecha_edicion     DATETIME      NULL,
  CONSTRAINT fk_plmsg_usuario FOREIGN KEY (creado_por) REFERENCES usuarios(idusuario) ON DELETE SET NULL,
  UNIQUE KEY uq_plmsg (categoria, titulo),
  INDEX idx_plmsg_cat (categoria, activo, orden)
) ENGINE=InnoDB;


SELECT 'Actualizacion 16 aplicada' AS resultado,
       (SELECT COUNT(*) FROM plantillas_mensajes) AS mensajes,
       (SELECT COUNT(DISTINCT categoria) FROM plantillas_mensajes) AS categorias;
